// Eligibility + compliance + throttle gate. Uses plain Date math for version-safety.
const openH = Number($env.BUSINESS_HOURS_START || 9);
const closeH = Number($env.BUSINESS_HOURS_END || 19);
if (!($now.hour >= openH && $now.hour < closeH)) return []; // only send in business hours
const today = $now.toISODate();
const dailyCap = Number($env.DAILY_CAP || 100);
const batch = Number($env.BATCH_SIZE || 20);
const rows = $input.all().map(i => i.json);
const dateOf = v => { const t = new Date(v).getTime(); return isNaN(t) ? '' : new Date(t).toISOString().slice(0,10); };
const sentToday = rows.filter(r => r.Sent_At && dateOf(r.Sent_At) === today).length;
const remaining = Math.max(0, dailyCap - sentToday);
const toSend = Math.min(batch, remaining);
if (toSend <= 0) return [];
const eligible = rows.filter(r => {
  const consent = String(r.Consent || '').toLowerCase() === 'yes';
  const optedOut = String(r.Opted_Out || '').toLowerCase() === 'yes';
  const alreadySent = !!r.Sent_At || String(r.Status || '').toLowerCase().includes('sent') || String(r.Status||'').toLowerCase().includes('opted');
  const hasPhone = !!String(r.Customer_Phone || '').trim();
  return consent && !optedOut && !alreadySent && hasPhone;
});
return eligible.slice(0, toSend).map(r => ({ json: r }));

