let body = (p.sms && p.sms.trim()) ? p.sms.trim() : `Hi${c.Customer_Name ? ' ' + String(c.Customer_Name).split(' ')[0] : ''}, it's ${biz} - we'd love to see you again! ${$env.OFFER || ''} ${$env.BOOKING_LINK || ''}`.trim();
